import { useState, useEffect, useContext } from "react";
import api from "../api";
import { AuthContext } from "../contexts/AuthContext";
import { useNavigate } from "react-router-dom";
import { 
  Home, Users, FileText, ListChecks, ClipboardList, LogOut 
} from "lucide-react"; // icons

export default function AdminDashboard() {
  const [votingOpen, setVotingOpen] = useState(false);
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [logs, setLogs] = useState([]);
  const [reportHash, setReportHash] = useState("");
  const [results, setResults] = useState({});
  const [winners, setWinners] = useState({});

  const { logout, token } = useContext(AuthContext);
  const navigate = useNavigate();

  // ---------------- Unified error handler ----------------
  const handleApiError = (err) => {
    console.error(err);
    if (err.response?.status === 401) {
      logout();
      navigate("/login");
    } else {
      alert(err.response?.data?.error || err.message);
    }
  };

  // ---------------- Backend API calls ----------------
  const fetchVotingState = async () => {
    try {
      const res = await api.get("/admin/voting-state");
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchPendingUsers = async () => {
    try {
      const res = await api.get("/admin/pending-users");
      setPendingUsers(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchCandidates = async () => {
    try {
      const res = await api.get("/admin/candidates");
      setCandidates(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchLogs = async () => {
    try {
      const res = await api.get("/admin/logs");
      setLogs(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const toggleVoting = async () => {
    try {
      const res = await api.post("/admin/toggle-voting");
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      handleApiError(err);
    }
  };

  const approveUser = async (id) => {
    try {
      await api.post(`/admin/approve-user/${id}`);
      fetchPendingUsers();
    } catch (err) {
      handleApiError(err);
    }
  };

  const rejectUser = async (id) => {
    try {
      await api.post(`/admin/reject-user/${id}`);
      fetchPendingUsers();
    } catch (err) {
      handleApiError(err);
    }
  };

  const generateReport = async () => {
    try {
      const res = await api.post("/admin/generate-report");
      setReportHash(res.data.hash);
    } catch (err) {
      handleApiError(err);
    }
  };

  const deleteCandidate = async (id) => {
    if (!window.confirm("Delete this candidate?")) return;
    try {
      await api.delete(`/admin/candidates/${id}`);
      fetchCandidates();
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchResults = async () => {
    try {
      const res = await api.get("/admin/results");
      setResults(res.data.positionResults);
      setWinners(res.data.winners);
    } catch (err) {
      handleApiError(err);
    }
  };

  // ---------------- Initial load ----------------
  useEffect(() => {
    if (!token) {
      navigate("/login");
      return;
    }

    const init = async () => {
      await fetchVotingState();
      await fetchPendingUsers();
      await fetchCandidates();
      await fetchLogs();
      await fetchResults();
    };
    init();
  }, [token]);

  // ---------------- JSX ----------------
  return (
    <div className="flex min-h-screen bg-gray-100">
      {/* Sidebar */}
      <aside className="w-64 bg-white border-r shadow-sm flex flex-col">
        <div className="h-16 flex items-center justify-center border-b">
          <h1 className="text-xl font-bold text-blue-700">iVote Admin</h1>
        </div>
        <nav className="flex-1 p-4 space-y-2">
          <NavItem icon={<Home size={18} />} label="Dashboard" />
          <NavItem icon={<Users size={18} />} label="Users" />
          <NavItem icon={<ListChecks size={18} />} label="Candidates" />
          <NavItem icon={<ClipboardList size={18} />} label="Results" />
          <NavItem icon={<FileText size={18} />} label="Reports" />
        </nav>
        <button
          onClick={() => { logout(); navigate("/login"); }}
          className="flex items-center gap-2 px-4 py-3 border-t hover:bg-gray-50 text-red-600 font-medium"
        >
          <LogOut size={18} /> Logout
        </button>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col">
        {/* Topbar */}
        <header className="h-16 bg-white border-b shadow-sm flex items-center px-6 justify-between">
          <h2 className="text-lg font-semibold text-gray-800">Admin Dashboard</h2>
        </header>

        <main className="p-6 space-y-8 overflow-y-auto">
          {/* Voting Status */}
          <Card>
            <div className="flex justify-between items-center">
              <div>
                <h3 className="text-lg font-semibold text-gray-800">Voting Status</h3>
                <p className={`mt-1 font-medium ${votingOpen ? "text-green-600" : "text-red-600"}`}>
                  {votingOpen ? "Open" : "Closed"}
                </p>
              </div>
              <button
                onClick={toggleVoting}
                className={`px-6 py-2 rounded-lg font-semibold text-white transition ${votingOpen ? "bg-red-600 hover:bg-red-700" : "bg-green-600 hover:bg-green-700"}`}
              >
                {votingOpen ? "Close Voting" : "Open Voting"}
              </button>
            </div>
          </Card>

          {/* Pending Users */}
          <Card title="Pending Voter Registrations">
            {pendingUsers.length === 0 ? (
              <p className="text-gray-500 italic">No pending users.</p>
            ) : (
              <Table
                headers={["Student Number", "Name", "Email", "Actions"]}
                rows={pendingUsers.map((u) => [
                  u.studentNumber,
                  u.name,
                  u.email,
                  <div className="space-x-2">
                    <button onClick={() => approveUser(u.id)} className="bg-green-600 text-white px-3 py-1 rounded hover:bg-green-700">Approve</button>
                    <button onClick={() => rejectUser(u.id)} className="bg-red-600 text-white px-3 py-1 rounded hover:bg-red-700">Reject</button>
                  </div>
                ])}
              />
            )}
          </Card>

          {/* Candidates */}
          <Card title="Candidates">
            <Table
              headers={["Name", "Position", "Party", "Actions"]}
              rows={candidates.map((c) => [
                c.name,
                c.position,
                c.party || "-",
                <button onClick={() => deleteCandidate(c.id)} className="bg-red-600 text-white px-3 py-1 rounded hover:bg-red-700">Delete</button>
              ])}
            />
          </Card>

          {/* Logs */}
          <Card title="System Logs">
            {logs.length === 0 ? (
              <p className="text-gray-500 italic">No logs available.</p>
            ) : (
              <ul className="space-y-2 max-h-64 overflow-y-auto text-sm">
                {logs.map((log) => (
                  <li key={log.id} className="flex justify-between border-b pb-1 text-gray-700">
                    <span>{log.action}</span>
                    <span className="text-gray-400">{new Date(log.createdAt).toLocaleString()}</span>
                  </li>
                ))}
              </ul>
            )}
          </Card>

          {/* Results */}
          <Card title="Election Results">
            {Object.keys(results).length === 0 ? (
              <p className="text-gray-500 italic">No results available yet.</p>
            ) : (
              Object.keys(results).map((pos) => (
                <div key={pos} className="mb-6">
                  <h4 className="text-md font-semibold text-gray-700 mb-2">{pos}</h4>
                  <Table
                    headers={["Name", "Party", "Votes", "Status"]}
                    rows={results[pos].map((c) => [
                      c.name,
                      c.party || "-",
                      c.votes,
                      winners[pos]?.id === c.id ? (
                        <span className="text-green-600 font-semibold">Winner</span>
                      ) : (
                        <span className="text-gray-400">—</span>
                      )
                    ])}
                  />
                </div>
              ))
            )}
          </Card>

          {/* Reports */}
          <Card title="Reports">
            <button
              onClick={generateReport}
              className="bg-blue-600 text-white px-5 py-2 rounded-lg hover:bg-blue-700 transition"
            >
              Generate Final Report
            </button>
            {reportHash && (
              <p className="mt-3 text-gray-600 text-sm">
                Cryptographic Hash: <span className="font-mono">{reportHash}</span>
              </p>
            )}
          </Card>
        </main>
      </div>
    </div>
  );
}

/* ------------------- Reusable Components ------------------- */
function Card({ children, title }) {
  return (
    <section className="bg-white p-6 rounded-xl shadow-sm border">
      {title && <h3 className="text-lg font-semibold text-gray-800 mb-4">{title}</h3>}
      {children}
    </section>
  );
}

function Table({ headers, rows }) {
  return (
    <div className="overflow-x-auto">
      <table className="w-full text-sm border border-gray-200 rounded-lg">
        <thead className="bg-gray-50 text-gray-700">
          <tr>
            {headers.map((h, i) => (
              <th key={i} className="px-4 py-2 text-left">{h}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row, i) => (
            <tr key={i} className="border-t hover:bg-gray-50">
              {row.map((cell, j) => (
                <td key={j} className="px-4 py-2">{cell}</td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function NavItem({ icon, label }) {
  return (
    <div className="flex items-center gap-2 px-3 py-2 rounded-lg hover:bg-gray-100 cursor-pointer text-gray-700">
      {icon}
      <span>{label}</span>
    </div>
  );
}
